var ALARM_STATE_VALUES2 = [0, 1];
function parseAlarmTimeToTimestamp3(alarmTime) {
  try {
    const trimmed = alarmTime.trim();
    if (trimmed.length < 13) {
      return null;
    }
    const datePart = trimmed.substring(0, 8);
    const timePart = trimmed.substring(8).trim();
    if (datePart.length !== 8 || timePart.length !== 6) {
      return null;
    }
    const year = parseInt(datePart.substring(0, 4), 10);
    const month = parseInt(datePart.substring(4, 6), 10);
    const day = parseInt(datePart.substring(6, 8), 10);
    const hour = parseInt(timePart.substring(0, 2), 10);
    const minute = parseInt(timePart.substring(2, 4), 10);
    const second = parseInt(timePart.substring(4, 6), 10);
    if (isNaN(year) || isNaN(month) || isNaN(day) || isNaN(hour) || isNaN(minute) || isNaN(second)) {
      return null;
    }
    if (month < 1 || month > 12) {
      return null;
    }
    if (day < 1 || day > 31) {
      return null;
    }
    if (hour < 0 || hour > 23) {
      return null;
    }
    if (minute < 0 || minute > 59) {
      return null;
    }
    if (second < 0 || second > 59) {
      return null;
    }
    const date = new Date(year, month - 1, day, hour, minute, second);
    const timestamp = date.getTime();
    if (isNaN(timestamp)) {
      return null;
    }
    return timestamp;
  } catch (error) {
    return null;
  }
}

