async function getFileUrls(wsManager, config, sessionId, taskId, messageId, toolCallId, fileInfos, udid) {
  const command = {
    header: {
      namespace: "Common",
      name: "Action"
    },
    payload: {
      cardParam: {},
      executeParam: {
        executeMode: "background",
        intentName: "FileUploadForClaw",
        bundleName: "com.huawei.hmos.vassistant",
        needUnlock: true,
        actionResponse: true,
        appType: "OHOS_APP",
        timeOut: 5,
        intentParam: {
          fileInfos,
          ...udid ? { udid } : {}
        },
        permissionId: [],
        achieveType: "INTENT"
      },
      responses: [
        {
          resultCode: "",
          displayText: "",
          ttsText: ""
        }
      ],
      needUploadResult: true,
      noHalfPage: false,
      pageControlRelated: false
    }
  };
  return new Promise((resolve2, reject) => {
    const timeout = setTimeout(() => {
      wsManager.off("data-event", handler);
      logger.error("\u8D85\u65F6: \u83B7\u53D6\u6587\u4EF6URL\u8D85\u65F6\uFF0860\u79D2\uFF09");
      reject(new Error("\u83B7\u53D6\u6587\u4EF6URL\u8D85\u65F6\uFF0860\u79D2\uFF09"));
    }, 6e4);
    const handler = (event) => {
      if (event.intentName === "FileUploadForClaw") {
        clearTimeout(timeout);
        wsManager.off("data-event", handler);
        if (event.status === "success" && event.outputs) {
          const code = event.outputs.code !== void 0 ? event.outputs.code : null;
          if (code !== null && code !== 0) {
            const errorMsg = event.outputs.errorMsg || event.outputs.errMsg || "\u672A\u77E5\u9519\u8BEF";
            reject(new Error(`\u83B7\u53D6\u6587\u4EF6URL\u5931\u8D25: ${errorMsg} (\u9519\u8BEF\u4EE3\u7801: ${code})`));
            return;
          }
          const outputs = event.outputs;
          const result = outputs?.result;
          let fileUrls = [];
          if (result && typeof result === "object") {
            const urls = result.fileUrls;
            if (Array.isArray(urls)) {
              fileUrls = urls;
            }
          }
          fileUrls = fileUrls.map((url) => {
            if (typeof url !== "string") {
              return "";
            }
            const decodedUrl = url.replace(/\\u003d/g, "=").replace(/\\u0026/g, "&");
            return decodedUrl;
          }).filter((url) => url.length > 0);
          resolve2(fileUrls);
        } else {
          reject(new Error(`\u83B7\u53D6\u6587\u4EF6URL\u5931\u8D25: ${JSON.stringify(event.outputs)}`));
        }
      }
    };
    wsManager.on("data-event", handler);
    sendCommand({
      config,
      sessionId,
      taskId,
      messageId,
      command,
      toolCallId
    }).then(() => {
    }).catch((error) => {
      clearTimeout(timeout);
      wsManager.off("data-event", handler);
      reject(error);
    });
  });
}

