  const body = JSON.stringify({
    useEdge: false,
    objectType: TEMPORARY_MATERIAL_PACKAGE,
    fileName,
    fileSha256,
    fileSize,
    fileOwnerInfo: {
      uid: FILE_OWNER_UID,
      teamId: FILE_OWNER_TEAM_ID
    }
  });
